def is_valid_square_orthogonal(grid, y, x, size, rows, cols):
    """Check if there's a valid axis-aligned square of size 'size' at top-left (y, x)"""
    # Square spans: rows [y, y+size-1], cols [x, x+size-1]
    # Minimum size is 2

    # Check border is all 1s
    for dy in range(size):
        if grid[y + dy][x] != '1' or grid[y + dy][x + size - 1] != '1':
            return False

    for dx in range(1, size - 1):
        if grid[y][x + dx] != '1' or grid[y + size - 1][x + dx] != '1':
            return False

    # Check no foreign 1s touch this square
    # Check all cells that could touch the square
    for dy_check in range(y - 1, y + size):
        for dx_check in range(x - 1, x + size):
            # Skip cells that are part of the square (border)
            if y - 1 <= dy_check <= y + size - 1 and x - 1 <= dx_check <= x + size - 1:
                # Check if this cell is part of the square border
                is_border = (dy_check == y or dy_check == y + size - 1 or dx_check == x or dx_check == x + size - 1)
                if not is_border:
                    continue
                if dy_check >= 0 and dy_check < rows and dx_check >= 0 and dx_check < cols:
                    if grid[dy_check][dx_check] != '1':
                        return False

    return True

def is_valid_square_diamond(grid, y, x, size, rows, cols):
    """Check if there's a valid diamond (rotated square) of size 'size' with top at (y, x)"""
    # For diamond: top (y,x), right (y+(size-1), x+(size-1)//2), bottom, left
    # Actually, diamond spans with size (radius from center), corner to corner

    # Diamond center is at (y + size//2, x + size//2)
    # Corners extend size-1 from center
    center_y = y + size // 2
    center_x = x + size // 2

    # Diamond occupies cells where distance from center in diamond metric <= size//2
    # Using coordinate transform: u = y - center_y, v = x - center_x
    # |u| + |v| <= size - 1

    # Check border (distance exactly size-1 in diamond metric)
    offset = size - 1

    for dy in range(-offset, offset + 1):
        dx_vals = []
        abs_dy = abs(dy)
        dx = offset - abs_dy
        dx_vals.extend([x - dx, x + dx, x + dx - dx, x + dx + dx])  # Wrong approach
        # Actually for diamond: |-dy| + |dx| = offset
        dx_limit = abs(offset - abs_dy)

        # For diamond boundary: |y - center_y| + |x - center_x| = offset
        for dx in range(-dx_limit, dx_limit + 1):
            if abs(dy) + abs(dx) == offset:
                yi = center_y + dy
                xi = center_x + dx
                if 0 <= yi < rows and 0 <= xi < cols:
                    if grid[yi][xi] != '1':
                        return False

    # Check no foreign 1s touch this diamond
    for dy_check in range(y - 2, y + size):
        for dx_check in range(x - 2, x + size):
            if 0 <= dy_check < rows and 0 <= dx_check < cols:
                cy = dy_check - center_y
                cx = dx_check - center_x
                dist = abs(cy) + abs(cx)

                # This cell touches diamond if dist <= offset + 1
                # Diamond cells have dist = offset
                if 0 < dist <= offset + 1:
                    if grid[dy_check][dx_check] == '1':
                        return False

    return True

