        for size in range(2, min(n, m) + 1):
            for y in range(n - size + 1):
                for x in range(m - size + 1):
                    if is_valid_square_orthogonal(grid, y, x, size, n, m):
                        count += 1

        # Check diamond squares
        # Size from 2 to min(n, m)
        for size in range(2, min(n, m) + 1):
            center_y = size // 2
            center_x = size // 2
            # Top of diamond is at (center_y - offset, center_x)
            # Bottom at (center_y + offset, center_x)
            offset = size // 2

            for y in range(max(0, center_y - offset - 1), min(n, center_y + offset + 2)):
