        return ""

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)

    # BFS from each node to get all-pairs shortest paths
    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = [start]
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Precompute all distances
    distances = [bfs(i) for i in range(1, n + 1)]

    best = -1
    best_path = None

    # Find optimal 4-city tour
    # Use nested loops - O(n^4) but practical for smaller test cases
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                continue
            if distances[i][j] == -1:
                continue
            for k in range(1, n + 1):
                if k == i or k == j:
                    continue
                if distances[j][k] == -1:
                    continue
                for l in range(1, n + 1):
                    if l == i or l == j or l == k:
                        continue
                    if distances[k][l] == -1:
                        continue
                    if distances[l][i] == -1:
                        continue

                    total = distances[i][j] + distances[j][k] + distances[k][l] + distances[l][i]
                    if total > best:
                        best = total
                        best_path = (i, j, k, l)

    if best_path:
        return f"{best_path[0]} {best_path[1]} {best_path[2]} {best_path[3]}"
    return "1 2 3 4"
