def solution(input_str):
    """
    Calculate the sum of f(s_i, s_j) for all pairs (i, j) where i < j.

    Returns a string with the result.
    """
    import sys
    from collections import Counter

    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:n + 1]

    total = 0

    # Helper function to get character signature (sorted tuple)
    def char_sig(s):
        return tuple(sorted(s))

    # Helper function to check if s2 can be obtained from s1 by sorting one substring
    def can_transform(s1, s2):
        if s1 == s2:
            return True
        len1 = len(s1)
        for i in range(len1):
            for j in range(i, len1 + 1):
                # Check substring s1[i:j]
                subs = s1[i:j]
                transformed = s1[:i] + ''.join(sorted(subs)) + s1[j:]
                if transformed == s2:
                    return True
        return False

    # Precompute character signatures
    sigs = {i: char_sig(strings[i]) for i in range(n)}

    for i in range(n):
        for j in range(i + 1, n):
            s1, s2 = strings[i], strings[j]

            if s1 == s2:
                continue  # f = 0

            if sigs[i] != sigs[j]:
                # Different character counts, impossible
                total += 1337
            else:
                # Same character counts, strings differ
                if can_transform(s1, s2):
                    total += 1  # One transformation needed
                else:
                    total += 2  # Both need to be sorted to canonical form

    return str(total) + '\n'
