def solution(s):
    MOD = 10**9 + 7
    n, k, m = map(int, s.strip().split())

    # Handle edge case: k = 1 means just choosing a starting planet
    if k == 1:
        return str(n)

    if k > n:
        return "0"

    # Due to constraints k ≤ 12 and m ≤ 4, we can use simplified DP
    # Process in reverse order: compute ways for different path lengths
    # ending at each planet within the relevant range

    # dp[i] = number of ways to have a valid path ending at planet i
    # We'll build this up for path lengths 1 to k

    MAX_POS = min(n, 100)  # In practice, path-localized computation

    # Initialize: for path length 1, each planet is reachable
    # dp_prev[i] = 1 for all i (single planet paths)
    dp_prev = [1] * (MAX_POS + 1)

    # Sum up all ways for path length 1
    ways_len_1 = MAX_POS if MAX_POS > 0 else 0

    for length in range(2, k + 1):
        dp_curr = [0] * (MAX_POS + 1)
        count_len = 0

        # For each possible ending planet at this path length
        for target in range(1, MAX_POS + 1):
            # From which planets can we reach 'target'?
            # Previous planet p must satisfy: target <= p + m => p >= target - m
            # Also: target != p (can't visit same planet twice)
            start_source = max(1, target - m)

            for source in range(start_source, min(target, MAX_POS + 1)):
                dp_curr[target] = (dp_curr[target] + dp_prev[source]) % MOD

        count_len = sum(dp_curr) % MOD

        # For final step (length k), this is the answer contribution
        if length == k:
            return str(count_len)

        dp_prev = dp_curr

    # If we get here, compute total
    return str(sum(dp_prev) % MOD) if sum(dp_prev) else "0"


