    # Build conflict graph
    conflict_graph = [[] for _ in range(len(roads))]
    for i in range(len(roads)):
        for j in range(i + 1, len(roads)):
            a, b = roads[i]
            c, d = roads[j]
            # Roads intersect if their intervals are interleaved
            if (a < c < b < d) or (c < a < d < b):
                conflict_graph[i].append(j)
                conflict_graph[j].append(i)

    # Check if bipartite using BFS
    color = {}
    for i in range(len(roads)):
