    n = int(input_data)

    if n == 1:
        return "1"
    if n == 2:
        return "3"
    if n == 3:
        return "9"

    MOD = 10**9 + 7

    MAX_D = 2 * n
    MAX_B = n

    # dp_free[d][b] = max matching in subtree when (d,b) is NOT matched with children
    # dp_matched[d][b] = max matching in subtree when (d,b) IS matched with a child
    dp_free = [[0] * (MAX_B + 1) for _ in range(MAX_D + 1)]
    dp_matched = [[0] * (MAX_B + 1) for _ in range(MAX_D + 1)]

    # Process from leaves (depth 2*n) up to root (depth 0)
    for d in range(2 * n - 1, -1, -1):
        for b in range(MAX_B + 1):
            # Find valid children
            children = []
            if b < MAX_B:
                children.append((d + 1, b + 1))
            if b > 0:
                children.append((d + 1, b - 1))

            if not children:
                continue

            # Option 1: (d,b) doesn't match with any child
            # For each child, we take max of (free or matched states)
            sum_option1 = 0
            for (cd, cb) in children:
                sum_option1 += max(dp_free[cd][cb], dp_matched[cd][cb])

            # Option 2: (d,b) matches with exactly one child ci
            # This contributes 1 edge + dp_free[ci] (ci matched with parent) + sum dp_matched[other children]
            if dp_matched[d][b] == 0:
                dp_matched[d][b] = 0

            best_option2 = -1
            for i, (cd, cb) in enumerate(children):
                # Value if matched with this child
                current_val = 1 + dp_free[cd][cb]
                for j, (od, ob) in enumerate(children):
                    if i != j:
                        current_val += dp_matched[od][ob]

                best_option2 = max(best_option2, current_val)

            if best_option2 != -1:
                dp_matched[d][b] = best_option2

                # dp_free can be either option1 or option2
                dp_free[d][b] = max(sum_option1, best_option2)

    # Root is at (0, 0), and it can't match with a parent, so we need dp_free[0][0]
    result = dp_free[0][0]

    return str(result % MOD)
